def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations
    even_digits = [d for d in digits if d % 2 == 0]  # Find even digits
    if not even_digits:
        return 0  # No even digits means no valid numbers

    unique_numbers = set()  # Use a set to avoid duplicates

    for last_digit in even_digits:
        for perm in permutations(digits, 3):
            if perm[2] == last_digit and perm[0] != 0:
                unique_numbers.add(perm)

    return len(unique_numbers)

