def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0]) if m > 0 else 0
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Initialize starting point with coins value
    dp[0][0][1] = max(0, coins[0][0])  # Neutralize if negative

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k represents neutralizations used
                if i + 1 < m:  # Move down
                    if coins[i + 1][j] >= 0:
                        dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k] + coins[i + 1][j])
                    else:
                        dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k] + coins[i + 1][j])  # Not neutralized
                        if k < 2:
                            dp[i + 1][j][k + 1] = max(dp[i + 1][j][k + 1], dp[i][j][k])  # Neutralized

                if j + 1 < n:  # Move right
                    if coins[i][j + 1] >= 0:
                        dp[i][j + 1][k] = max(dp[i][j + 1][k], dp[i][j][k] + coins[i][j + 1])
                    else:
                        dp[i][j + 1][k] = max(dp[i][j + 1][k], dp[i][j][k] + coins[i][j + 1])  # Not neutralized
                        if k < 2:
                            dp[i][j + 1][k + 1] = max(dp[i][j + 1][k + 1], dp[i][j][k])  # Neutralized

    return max(dp[m - 1][n - 1][0], dp[m - 1][n - 1][1], dp[m - 1][n - 1][2])

from typing import List


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    # Create adjacency list for the original graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))  # Forward graph for original edges

    # Function to check if all nodes can reach 0 under max_weight and threshold
    def canReachAll(max_weight):
        out_degree = [0] * n
        visited = [False] * n

        # Count out-degrees for nodes with edges that have weight <= max_weight
        for node in range(n):
            for neighbor, weight in graph[node]:
                if weight <= max_weight:
                    out_degree[node] += 1

        # Perform BFS for each node 1 to n-1 to see if they can reach node 0
        for start_node in range(1, n):
            if visited[start_node]:
                continue
            queue = deque([start_node])
            visited[start_node] = True

            while queue:
                current = queue.popleft()
                for neighbor, weight in graph[current]:
                    if weight <= max_weight:
                        if out_degree[current] >= threshold:
                            continue  # Skip if threshold exceeded
                        out_degree[current] += 1
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        # Check if all nodes are visited
        return all(visited[1:])  # Skip node 0 since it doesn't need to reach itself

    # Binary search for the minimum possible maximum weight
    left, right = 1, 10**6
    answer = -1
    while left <= right:
        mid = (left + right) // 2
        if canReachAll(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    return answer

